$params = @{
    Identity = 'Finance Policy'
    Member = 'Finance Documents Rule', 'Corporate Documents Rule'
}
Add-ADCentralAccessPolicyMember @params

$userParams = @{
    Identity = 'CN=Chew David,OU=UserAccounts,DC=NORTHAMERICA,DC=FABRIKAM,DC=COM'
    Server = 'northamerica.fabrikam.com'
}
$User = Get-ADUser @userParams
$groupParams = @{
    Identity = 'CN=AccountLeads,OU=UserAccounts,DC=EUROPE,DC=FABRIKAM,DC=COM'
    Server = 'europe.fabrikam.com'
}
$Group = Get-ADGroup @groupParams
Add-ADGroupMember -Identity $Group -Members $User -Server "europe.fabrikam.com"

$params = @{
    Identity = 'Global Resource Property List'
    Members = 'Country', 'Authors'
}
Add-ADResourcePropertyListMember @params

{
  "$schema": "schema.json",
  "actions": [
      {
        "verb": "setSiteLogo",
        "url": "https://contoso.sharepoint.com/SiteAssets/company-logo.png"
      }
  ]
}

Get-Content 'c:\scripts\site-script.json' -Raw | Add-SPOSiteScript -Title "Customer logo" -Description "Applies customer logo for customer sites"

$manifestContent = @'
{
  "$schema": "schema.json",
  "actions": [
      {
        "verb": "importBusinessApps",
        "listName": "Contoso list",
        "solutionRelativeFilePath": "solution.zip"
      }
  ]
}
'@;
Set-Content "manifest.json" $manifestContent
$compress = @{
  Path = ".\manifest.json", ".\solution.zip"
  DestinationPath = "c:\scripts\site-script-package.zip"
}
Compress-Archive @compress

Add-SPOSiteScriptPackage -Title "Install Contoso flow" -Description "Installs the new Contoso flow in a list" -ContentPath "c:\scripts\site-script-package.zip"
